// ——— Récompenses quotidiennes ———
// Un jour = une date du calendrier local. Une récompense par jour ; le 7e jour est plus gros ; le 8e jour, un nouveau cycle commence.
// Pas de remise à zéro si le joueur saute des jours : il reprend où il en était.
// Récompenses provisoires (Bubulles) : on les remplacera ensemble. Une ligne par cycle ; le dernier cycle se répète.
const DAILY_REWARDS=[[{gold:30},{gold:30},{gold:30},{gold:30},{gold:30},{gold:30},{gold:100,big:true}]];
const todayKey=(d=new Date())=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
function dailyState(){const d=profile.daily&&typeof profile.daily==='object'?profile.daily:{},day=Number.isInteger(d.day)&&d.day>=0&&d.day<=7?d.day:0,cycle=Number.isInteger(d.cycle)&&d.cycle>=0?d.cycle:0,last=typeof d.last==='string'?d.last:'';
 const claimable=last!==todayKey(),fresh=claimable&&day>=7;return{day:fresh?0:day,cycle:fresh?cycle+1:cycle,last,claimable}}
function dailyRewards(cycle){return DAILY_REWARDS[Math.min(cycle,DAILY_REWARDS.length-1)]}
function rewardLabel(r){return r.gold?r.gold.toLocaleString('fr-FR')+' Bubulles':'Récompense'}
function claimDaily(){const st=dailyState();if(!st.claimable||!storageOK)return;const r=dailyRewards(st.cycle)[st.day],next=structuredClone(profile);if(r.gold)next.gold+=r.gold;next.daily={day:st.day+1,cycle:st.cycle,last:todayKey()};
 if(commit(next)){drawDaily();updateDailyDie();toast('Jour '+(st.day+1)+' : '+rewardLabel(r)+' récupérées !')}}
function drawDaily(){const box=$('daily-body');if(!box)return;const st=dailyState(),list=dailyRewards(st.cycle);
 box.innerHTML='<ol class="daily-days">'+list.map((r,i)=>{const done=i<st.day,today=st.claimable&&i===st.day,cls=(done?'done':today?'today':'todo')+(r.big?' big':'');return `<li class="daily-day ${cls}"><span class="daily-n">Jour ${i+1}</span><span class="daily-gift" aria-hidden="true">${done?'✓':r.big?'🎁':'<img src="assets/bubulle.webp" width="26" height="26" alt="">'}</span><span class="daily-r">${rewardLabel(r)}</span></li>`}).join('')+'</ol>'+
 (st.claimable?'<button class="portal-primary daily-claim" data-daily="claim">Récupérer le jour '+(st.day+1)+'</button>':'<p class="daily-wait">Récompense du jour récupérée ! Revenez demain pour '+(st.day>=7?'commencer un nouveau cycle de récompenses.':'le jour '+(st.day+1)+'.')+'</p>')}
function updateDailyDie(){const b=$('daily-die');if(!b)return;const st=dailyState();b.classList.toggle('ready',st.claimable);b.setAttribute('aria-label',st.claimable?'Récompense quotidienne disponible':'Récompenses quotidiennes');b.querySelector('.daily-count').textContent=st.claimable?'!':st.day+'/7'}
(function setupDaily(){const b=document.createElement('button');b.id='daily-die';b.type='button';b.innerHTML='<span class="daily-stage" aria-hidden="true"><span class="daily-cube"><u class="dcore"></u><u class="dcore y"></u><u class="dcore z"></u>'+[['f',[4]],['k',[0,2,3,5,6,8]],['r',[0,8]],['l',[0,2,6,8]],['t',[0,4,8]],['m',[0,2,4,6,8]]].map(([f,p])=>'<i class="dc-'+f+'">'+Array.from({length:9},(_,k)=>'<b'+(p.includes(k)?' class="on"':'')+'></b>').join('')+'</i>').join('')+'</span></span><span class="daily-label">Quotidien</span><span class="daily-count"></span>';
 document.querySelector('#portal .portal-head')?.append(b);const dlg=document.createElement('dialog');dlg.id='daily-dialog';dlg.setAttribute('aria-labelledby','daily-title');dlg.innerHTML='<header><h2 id="daily-title">Récompenses quotidiennes</h2><button type="button" data-daily="close" aria-label="Fermer">✕</button></header><p class="daily-intro">Connectez-vous chaque jour : une récompense par jour, et une plus grosse le 7<sup>e</sup> jour !</p><div id="daily-body"></div>';document.body.append(dlg);
 b.onclick=()=>{drawDaily();dlg.showModal()};dlg.addEventListener('click',e=>{const a=e.target.closest('[data-daily]')?.dataset.daily;if(a==='close'||e.target===dlg)dlg.close();else if(a==='claim')claimDaily()});updateDailyDie();document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateDailyDie()})})();
window.HackeniaPortal={open:v=>navigate(v,true),profile:()=>profile,commit:next=>commit(next),validate:p=>validate(structuredClone(p)),restore(p){const next=validate(structuredClone(p));if(!commit(next))return false;storageOK=true;recovery=false;draft={id:null,name:'Nouveau deck',dice:[]};saveDraft();render();return true},toast:t=>toast(t),playableDecks:()=>profile.decks.filter(d=>legal(d.dice)),preferredDeck:()=>{const a=profile.decks.filter(d=>legal(d.dice));return a.find(d=>d.id===profile.preferredDeckId)||a[0]||null},planPouch:p=>window.HackeniaPurchases.plan(p,1),afterTutorial(){if(hasSavedProfile)navigate('home',true);else showStartMenu()}};
